files.content:
// CodeMirror for the repo IDE, loaded when an editor first mounts: the page that shows a repo pays
// for the editor only then, and a file's language pack loads with the file. Everything below takes
// the loaded modules (`CodeMirror`) rather than importing them, so no module of the IDE holds
// CodeMirror in its static imports.
import type { EditorState, Extension, RangeSet } from "@codemirror/state";
import type { GutterMarker } from "@codemirror/view";
import type { RepoFileLanguage } from "./repo-file-kinds.ts";

async function loadLanguage(language: RepoFileLanguage): Promise<Extension> {
  switch (language) {
    case "css":
      return (await import("@codemirror/lang-css")).css();
    case "html":
      return (await import("@codemirror/lang-html")).html();
    case "javascript":
      return (await import("@codemirror/lang-javascript")).javascript({ jsx: true });
    case "typescript":
      return (await import("@codemirror/lang-javascript")).javascript({
        jsx: true,
        typescript: true,
      });
    case "json":
    case "jsonc":
      return (await import("@codemirror/lang-json")).json();
    case "markdown":
      return (await import("@codemirror/lang-markdown")).markdown();
    case "sql":
      return (await import("@codemirror/lang-sql")).sql();
    case "yaml":
      return (await import("@codemirror/lang-yaml")).yaml();
    case "text":
      return [];
  }
}

export async function loadCodeMirror(language: RepoFileLanguage) {
  const [view, state, merge, setup, themes, languageSupport] = await Promise.all([
    import("@codemirror/view"),
    import("@codemirror/state"),
    import("@codemirror/merge"),
    import("codemirror"),
    import("@fsegurai/codemirror-theme-bundle"),
    loadLanguage(language),
  ]);
  return {
    view,
    state,
    merge,
    basicSetup: setup.basicSetup,
    vsCodeLight: themes.vsCodeLight,
    languageSupport,
  };
}

export type CodeMirror = Awaited<ReturnType<typeof loadCodeMirror>>;

type ChangeKind = "added" | "deleted" | "modified";

/** vscode-style change indicators for a plain editor: a thin coloured bar in the gutter on every
 *  line that differs from `original`: green for added lines, blue for modified, red at a deletion.
 *  Recomputed per edit against the snapshot it was made with. */
function changedLinesGutter(cm: CodeMirror, original: string): Extension {
  const { GutterMarker: GutterMarkerBase, EditorView, gutter } = cm.view;
  const { RangeSetBuilder, StateField } = cm.state;

  class ChangedLineMarker extends GutterMarkerBase {
    readonly kind: ChangeKind;

    constructor(kind: ChangeKind) {
      super();
      this.kind = kind;
    }

    // a child element, not a background on the gutter element: the active-line gutter theme
    // overrides gutter backgrounds, which would hide the bar on the cursor line
    toDOM(): Node {
      const bar = document.createElement("div");
      bar.className = `cm-changed-line-bar cm-changed-line-${this.kind}`;
      return bar;
    }
  }
  const markers: Record<ChangeKind, ChangedLineMarker> = {
    added: new ChangedLineMarker("added"),
    deleted: new ChangedLineMarker("deleted"),
    modified: new ChangedLineMarker("modified"),
  };

  const markersFor = (state: EditorState): RangeSet<GutterMarker> => {
    const kinds = new Map<number, ChangeKind>();
    for (const change of cm.merge.presentableDiff(original, state.doc.toString())) {
      if (change.fromB === change.toB) {
        // a pure deletion marks the line it happened at
        const line = state.doc.lineAt(Math.min(change.fromB, state.doc.length)).number;
        if (!kinds.has(line)) kinds.set(line, "deleted");
        continue;
      }
      const kind: ChangeKind = change.fromA === change.toA ? "added" : "modified";
      const fromLine = state.doc.lineAt(change.fromB).number;
      const toLine = state.doc.lineAt(Math.min(change.toB, state.doc.length)).number;
      for (let line = fromLine; line <= toLine; line++) kinds.set(line, kind);
    }
    const builder = new RangeSetBuilder<GutterMarker>();
    for (const line of [...kinds.keys()].toSorted((a, b) => a - b)) {
      const from = state.doc.line(line).from;
      builder.add(from, from, markers[kinds.get(line)!]);
    }
    return builder.finish();
  };

  const field = StateField.define<RangeSet<GutterMarker>>({
    create: (state) => markersFor(state),
    update: (value, transaction) =>
      transaction.docChanged ? markersFor(transaction.state) : value,
  });
  return [
    field,
    gutter({ class: "cm-changed-lines-gutter", markers: (view) => view.state.field(field) }),
    EditorView.baseTheme({
      ".cm-changed-lines-gutter": { width: "3px" },
      ".cm-changed-line-bar": { width: "3px", height: "100%", borderRadius: "2px" },
      ".cm-changed-line-added": { backgroundColor: "#2da44e" },
      ".cm-changed-line-modified": { backgroundColor: "#0969da" },
      ".cm-changed-line-deleted": { backgroundColor: "#cf222e" },
    }),
  ];
}

/** The editor's view of a baseline: the gutter bars, or the inline diff, whose chunk controls (when
 *  `onAcceptChunk` is given) stage a chunk: accepting one applies it to the merge view's original
 *  doc, which this reports whole. */
function baselineExtensions(
  cm: CodeMirror,
  input: {
    baseline: string;
    diff: boolean;
    onAcceptChunk: ((baseline: string) => void) | undefined;
  },
): Extension {
  if (!input.diff) return changedLinesGutter(cm, input.baseline);
  const { EditorView } = cm.view;
  const { onAcceptChunk } = input;
  return [
    cm.merge.unifiedMergeView({
      original: input.baseline,
      allowInlineDiffs: true,
      mergeControls: onAcceptChunk
        ? (type, action) => {
            const button = document.createElement("button");
            button.textContent = type === "accept" ? "+" : "⨯";
            button.title = type === "accept" ? "Stage block" : "Discard block";
            button.onmousedown = action;
            return button;
          }
        : false,
    }),
    onAcceptChunk
      ? EditorView.updateListener.of((update) => {
          const original = cm.merge.getOriginalDoc(update.state);
          if (original.eq(cm.merge.getOriginalDoc(update.startState))) return;
          onAcceptChunk(original.toString());
        })
      : [],
    EditorView.baseTheme({
      ".cm-chunkButtons button": {
        cursor: "pointer",
        border: "1px solid #d0d7de",
        borderRadius: "3px",
        background: "#fff",
        margin: "0 1px",
        padding: "0 5px",
        fontSize: "11px",
        lineHeight: "16px",
      },
    }),
  ];
}

export function editorExtensions(
  cm: CodeMirror,
  input: {
    language: RepoFileLanguage;
    readOnly: boolean;
    label: string;
    baseline: string | undefined;
    diff: boolean;
    onAcceptChunk: ((baseline: string) => void) | undefined;
    onChange: (value: string) => void;
  },
): Extension[] {
  const { EditorView } = cm.view;
  return [
    cm.basicSetup,
    cm.vsCodeLight,
    cm.languageSupport,
    cm.state.EditorState.readOnly.of(input.readOnly),
    EditorView.editable.of(!input.readOnly),
    // the editor's accessible name: its content is the textbox
    EditorView.contentAttributes.of({ "aria-label": input.label }),
    // prose wraps; code scrolls
    input.language === "markdown" ? EditorView.lineWrapping : [],
    EditorView.updateListener.of((update) => {
      if (update.docChanged) input.onChange(update.state.doc.toString());
    }),
    EditorView.theme({
      "&": { height: "100%", fontSize: "12px" },
      "&.cm-focused": { outline: "none" },
      ".cm-scroller": { overflow: "auto", fontFamily: "var(--font-mono, monospace)" },
      ".cm-activeLine, .cm-activeLineGutter": { backgroundColor: "transparent" },
    }),
    // a baseline of "" is an empty file, a missing one is no baseline at all
    // oxlint-disable-next-line iterate/simple-truthiness-check -- "" is a baseline, undefined is none
    input.baseline === undefined
      ? []
      : baselineExtensions(cm, {
          baseline: input.baseline,
          diff: input.diff,
          onAcceptChunk: input.onAcceptChunk,
        }),
  ];
}

import { EmptyPane, ErrorPane, FileChrome } from "./file-chrome.tsx";
import { RepoCodeEditor } from "./repo-code-editor.tsx";
import { repoFileKind } from "./repo-file-kinds.ts";
import { readRepoFile, useRead, type RepoProject } from "./repo-client.ts";

/**
 * Readonly diff of one file in one commit against that commit's first parent: what opens when a
 * changed file is clicked in the History view. The same readonly diff as the staged (Index) view:
 * lock icon, no chunk controls, no input.
 */
export function CommitDiffPane({
  project,
  repoPath,
  path,
  commit,
}: {
  project: RepoProject;
  repoPath: string;
  path: string;
  commit: { oid: string; parents: string[] };
}) {
  const kind = repoFileKind(path);
  const parentOid = commit.parents[0];
  const sides = useRead(async () => {
    if (kind.kind !== "text") return null;
    const [before, after] = await Promise.all([
      // the content before the commit: none for a root commit
      !parentOid ? undefined : readRepoFile(project, repoPath, path, parentOid),
      readRepoFile(project, repoPath, path, commit.oid),
    ]);
    return { before, after };
  }, [project, repoPath, path, commit.oid, parentOid, kind.kind]);

  const suffix = `(${commit.oid.slice(0, 7)})`;
  if (kind.kind !== "text") {
    return (
      <FileChrome path={path} suffix={suffix} readonly>
        <EmptyPane label="Binary file: the repo editor shows text files only." />
      </FileChrome>
    );
  }
  if (sides.status !== "loaded" || !sides.value) {
    return (
      <FileChrome path={path} suffix={suffix} readonly>
        {sides.status === "failed" ? (
          <ErrorPane message={sides.message} />
        ) : (
          <EmptyPane label={`Loading ${path}…`} spinner />
        )}
      </FileChrome>
    );
  }
  const { before, after } = sides.value;
  // undefined is a file not in that commit, "" an empty one
  // oxlint-disable-next-line iterate/simple-truthiness-check -- an empty file is not a missing one
  if (before === undefined && after === undefined) {
    return (
      <FileChrome path={path} suffix={suffix} readonly>
        <EmptyPane label={`${path} is not in ${commit.oid.slice(0, 7)} or its parent.`} />
      </FileChrome>
    );
  }
  // oxlint-disable-next-line iterate/simple-truthiness-check -- an empty file is not a missing one
  const status = before === undefined ? "added" : after === undefined ? "deleted" : "modified";
  return (
    <FileChrome path={path} suffix={suffix} readonly status={status}>
      <RepoCodeEditor
        key={`${path}:${commit.oid}`}
        className="min-h-0 flex-1"
        readOnly
        label={path}
        value={after || ""}
        language={kind.language}
        baseline={before || ""}
        diff
      />
    </FileChrome>
  );
}

import { ChevronDownIcon, ChevronRightIcon } from "lucide-react";
import type { RepoLogEntry } from "iterate/api";
import { readChangedFiles, useRead, type RepoProject } from "./repo-client.ts";

/** A moment as `2026-09-30 15:39 UTC`: the same on the server and in the browser, whatever the
 *  reader's locale. */
function utcStamp(timestamp: number) {
  return `${new Date(timestamp).toISOString().slice(0, 16).replace("T", " ")} UTC`;
}

/** How long ago, in the coarsest whole unit. */
function timeAgo(timestamp: number) {
  const seconds = Math.max(0, Math.round((Date.now() - timestamp) / 1000));
  for (const [unit, size] of [
    ["d", 86_400],
    ["h", 3_600],
    ["m", 60],
  ] as const) {
    if (seconds >= size) return `${Math.floor(seconds / size)}${unit} ago`;
  }
  return "just now";
}

/**
 * The History sidebar of the repo IDE: a linear newest-first commit list (repos are single-branch,
 * so no graph). Expanding a row reads the files the commit changed; clicking one opens the
 * readonly parent-against-commit diff.
 */
export function CommitHistoryPanel({
  commits,
  project,
  repoPath,
  expandedOid,
  selectedPath,
  onExpand,
  onOpenFile,
}: {
  commits: RepoLogEntry[];
  project: RepoProject;
  repoPath: string;
  /** The commit whose row is expanded (URL-owned view state). */
  expandedOid: string | undefined;
  /** The file open in the diff pane, to highlight its row. */
  selectedPath: string | undefined;
  onExpand: (oid: string | undefined) => void;
  onOpenFile: (path: string) => void;
}) {
  return (
    <div className="flex h-full min-h-0 flex-col">
      <div className="flex shrink-0 items-center justify-between border-b px-3 py-2">
        <span className="text-[11px] font-semibold tracking-wide text-muted-foreground uppercase">
          History
        </span>
        <span className="text-[11px] text-muted-foreground">
          main · {commits.length} commit{commits.length === 1 ? "" : "s"}
        </span>
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto py-1">
        {commits.map((commit) => {
          const expanded = commit.oid === expandedOid;
          return (
            <div key={commit.oid}>
              <button
                type="button"
                className="flex w-full items-start gap-1.5 px-2 py-1.5 text-left hover:bg-accent"
                onClick={() => onExpand(expanded ? undefined : commit.oid)}
              >
                {expanded ? (
                  <ChevronDownIcon className="mt-0.5 size-3.5 shrink-0 text-muted-foreground" />
                ) : (
                  <ChevronRightIcon className="mt-0.5 size-3.5 shrink-0 text-muted-foreground" />
                )}
                <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                  <span className="truncate text-xs" title={commit.message}>
                    {commit.message.split("\n")[0]}
                  </span>
                  <span className="flex items-center gap-1.5 text-[11px] text-muted-foreground">
                    <span className="min-w-0 truncate">{commit.author.name}</span>
                    <span className="shrink-0">{timeAgo(commit.timestamp)}</span>
                    <span className="ml-auto shrink-0 font-mono">{commit.oid.slice(0, 7)}</span>
                  </span>
                </span>
              </button>
              {expanded ? (
                <ExpandedCommit
                  commit={commit}
                  project={project}
                  repoPath={repoPath}
                  selectedPath={selectedPath}
                  onOpenFile={onOpenFile}
                />
              ) : null}
            </div>
          );
        })}
      </div>
    </div>
  );
}

/** The expanded commit: its full message, author, and the files it changed. */
function ExpandedCommit({
  commit,
  project,
  repoPath,
  selectedPath,
  onOpenFile,
}: {
  commit: RepoLogEntry;
  project: RepoProject;
  repoPath: string;
  selectedPath: string | undefined;
  onOpenFile: (path: string) => void;
}) {
  // a commit's diff against its parent never changes, so it is read once per expansion
  const files = useRead(
    () => readChangedFiles(project, repoPath, commit),
    [project, repoPath, commit.oid],
  );
  const parent = commit.parents[0];
  return (
    <div className="mx-2 mb-1.5 flex flex-col gap-1.5 rounded-sm border bg-muted/30 px-2.5 py-2">
      <p className="text-xs whitespace-pre-wrap">{commit.message}</p>
      <div className="flex flex-col gap-0.5 text-[11px] text-muted-foreground">
        <span className="truncate" title={commit.author.email}>
          {commit.author.name} &lt;{commit.author.email}&gt;
        </span>
        <span>{utcStamp(commit.timestamp)}</span>
        <span className="font-mono">
          {commit.oid.slice(0, 7)}
          {!parent ? " (root commit)" : ` ← ${parent.slice(0, 7)}`}
        </span>
      </div>
      <div className="flex flex-col gap-0.5 border-t pt-1.5">
        {files.status === "pending" ? (
          <span className="text-[11px] text-muted-foreground" data-spinner="true">
            Loading commit…
          </span>
        ) : files.status === "failed" ? (
          <span role="alert" data-type="error" className="text-[11px] text-destructive">
            {files.message}
          </span>
        ) : files.value.length === 0 ? (
          <span className="text-[11px] text-muted-foreground">No file changes.</span>
        ) : (
          files.value.map((file) => (
            <button
              key={file.path}
              type="button"
              className={`flex items-center gap-1.5 rounded-sm px-1 py-0.5 text-left hover:bg-accent ${file.path === selectedPath ? "bg-accent" : ""}`}
              title={file.path}
              onClick={() => onOpenFile(file.path)}
            >
              <span
                className={
                  file.status === "deleted"
                    ? "w-3 shrink-0 font-mono text-xs font-semibold text-red-600"
                    : file.status === "added"
                      ? "w-3 shrink-0 font-mono text-xs font-semibold text-green-600"
                      : "w-3 shrink-0 font-mono text-xs font-semibold text-blue-600"
                }
              >
                {file.status === "deleted" ? "D" : file.status === "added" ? "A" : "M"}
              </span>
              <span className="min-w-0 flex-1 truncate font-mono text-xs">{file.path}</span>
            </button>
          ))
        )}
      </div>
    </div>
  );
}

import type { ReactNode } from "react";
import { LockIcon } from "lucide-react";
import { Badge } from "#/components/ui/badge.tsx";
import { Tabs, TabsList, TabsTrigger } from "#/components/ui/tabs.tsx";

/** Shared editor-pane chrome: the path header, a status badge and an actions slot. */
export function FileChrome({
  path,
  suffix,
  readonly = false,
  status,
  leading,
  actions,
  children,
}: {
  path: string;
  /** vscode-style pseudo-file name: "(Index)", "(Working Tree)". */
  suffix?: string;
  readonly?: boolean;
  status?: "added" | "deleted" | "modified";
  /** Top-left slot before the path: the Code | Preview toggle lives here. */
  leading?: ReactNode;
  actions?: ReactNode;
  children: ReactNode;
}) {
  return (
    <div className="flex min-h-0 min-w-0 flex-1 flex-col">
      <div className="flex h-9 shrink-0 items-center gap-2 border-b px-3">
        {leading}
        <span className="min-w-0 truncate font-mono text-xs">
          {path}
          {suffix ? <span className="text-muted-foreground"> {suffix}</span> : null}
        </span>
        {readonly ? <LockIcon className="size-3 shrink-0 text-muted-foreground" /> : null}
        {status ? (
          <Badge
            variant={status === "deleted" ? "destructive" : "secondary"}
            className="text-[10px]"
          >
            {status}
          </Badge>
        ) : null}
        <div className="ml-auto flex items-center gap-1">{actions}</div>
      </div>
      {children}
    </div>
  );
}

/** The "Code | Preview" tab pair for previewable (markdown, html) files. */
export function CodePreviewToggle({
  preview,
  onChange,
}: {
  preview: boolean;
  onChange: (preview: boolean) => void;
}) {
  return (
    <Tabs
      value={preview ? "preview" : "code"}
      onValueChange={(value) => onChange(value === "preview")}
      className="shrink-0"
    >
      <TabsList className="h-7">
        <TabsTrigger value="code" className="px-2 text-xs">
          Code
        </TabsTrigger>
        <TabsTrigger value="preview" className="px-2 text-xs">
          Preview
        </TabsTrigger>
      </TabsList>
    </Tabs>
  );
}

export function EmptyPane({ label, spinner = false }: { label: string; spinner?: boolean }) {
  return (
    <div
      className="flex flex-1 items-center justify-center text-sm text-muted-foreground"
      {...(spinner ? { "data-spinner": "true" } : {})}
    >
      {label}
    </div>
  );
}

export function ErrorPane({ message }: { message: string }) {
  return (
    <div role="alert" data-type="error" className="p-4 text-sm text-destructive">
      {message}
    </div>
  );
}

import { useState, type ReactNode } from "react";
import { GitCommitVerticalIcon, MinusIcon, PlusIcon, Undo2Icon } from "lucide-react";
import { commitPlan, type FileEntry, type WorkingTreeChanges } from "./staged-changes.ts";
import { Button } from "#/components/ui/button.tsx";
import { Input } from "#/components/ui/input.tsx";

type ChangeStatus = "added" | "deleted" | "modified";

const STATUS_LETTERS: Record<ChangeStatus, { letter: string; className: string }> = {
  added: { letter: "A", className: "text-green-600" },
  deleted: { letter: "D", className: "text-red-600" },
  modified: { letter: "M", className: "text-blue-600" },
};

/** What the Source Control sidebar does: the IDE owns the working tree. */
export interface GitPanelActions {
  commit: (message: string, onCommitted: () => void) => void;
  stage: (path: string) => void;
  unstage: (path: string) => void;
  discard: (path: string) => void;
  discardAll: () => void;
  open: (path: string, status: ChangeStatus) => void;
  openStaged: (path: string) => void;
}

/** The Source Control sidebar: commit box on top, then Staged Changes and Changes (vscode's shape,
 *  a file appearing in both when it was edited again after staging). Commit takes the staged
 *  snapshots when anything is staged, otherwise everything. */
export function GitPanel({
  changes,
  headPathSet,
  commitPending,
  actions,
}: {
  changes: WorkingTreeChanges;
  headPathSet: ReadonlySet<string>;
  commitPending: boolean;
  actions: GitPanelActions;
}) {
  const staged = [...changes].flatMap(([path, change]) =>
    change.staged ? [{ path, entry: change.staged }] : [],
  );
  const working = [...changes].flatMap(([path, change]) =>
    change.working ? [{ path, entry: change.working }] : [],
  );
  const statusOf = (path: string, entry: FileEntry): ChangeStatus => {
    if (entry.type === "delete") return "deleted";
    return headPathSet.has(path) ? "modified" : "added";
  };
  return (
    <div className="flex h-full min-h-0 flex-col">
      <CommitForm changes={changes} pending={commitPending} onCommit={actions.commit} />
      <div className="flex min-h-0 flex-1 flex-col overflow-y-auto pb-2">
        {staged.length > 0 ? (
          <>
            <SectionHeader
              title="Staged Changes"
              buttons={
                <IconButton
                  title="Unstage all"
                  onClick={() => staged.forEach(({ path }) => actions.unstage(path))}
                >
                  <MinusIcon className="size-3" />
                </IconButton>
              }
            />
            <div className="flex flex-col gap-0.5 px-1.5">
              {staged.map(({ path, entry }) => (
                <ChangeRow
                  key={path}
                  path={path}
                  status={statusOf(path, entry)}
                  onOpen={() => actions.openStaged(path)}
                  buttons={
                    <IconButton title="Unstage change" onClick={() => actions.unstage(path)}>
                      <MinusIcon className="size-3" />
                    </IconButton>
                  }
                />
              ))}
            </div>
          </>
        ) : null}
        <SectionHeader
          title="Changes"
          buttons={
            working.length > 0 ? (
              <>
                <IconButton title="Discard all changes" onClick={actions.discardAll}>
                  <Undo2Icon className="size-3" />
                </IconButton>
                <IconButton
                  title="Stage all changes"
                  onClick={() => working.forEach(({ path }) => actions.stage(path))}
                >
                  <PlusIcon className="size-3" />
                </IconButton>
              </>
            ) : null
          }
        />
        <div className="flex flex-col gap-0.5 px-1.5">
          {working.length === 0 ? (
            <span className="px-1.5 py-2 text-xs text-muted-foreground">No changes.</span>
          ) : (
            working.map(({ path, entry }) => {
              const status = statusOf(path, entry);
              return (
                <ChangeRow
                  key={path}
                  path={path}
                  status={status}
                  onOpen={() => actions.open(path, status)}
                  buttons={
                    <>
                      <IconButton title="Discard changes" onClick={() => actions.discard(path)}>
                        <Undo2Icon className="size-3" />
                      </IconButton>
                      <IconButton title="Stage change" onClick={() => actions.stage(path)}>
                        <PlusIcon className="size-3" />
                      </IconButton>
                    </>
                  }
                />
              );
            })
          )}
        </div>
      </div>
    </div>
  );
}

/** The message box and Commit button. A form action, so submitting needs no handler of its own. */
function CommitForm({
  changes,
  pending,
  onCommit,
}: {
  changes: WorkingTreeChanges;
  pending: boolean;
  onCommit: (message: string, onCommitted: () => void) => void;
}) {
  const [message, setMessage] = useState("");
  const plan = commitPlan(changes);
  const disabled = changes.size === 0 || pending;
  let label = `Commit ${plan.paths.length || ""}`;
  if (pending) label = "Committing…";
  else if (plan.mode === "staged") label = `Commit ${plan.paths.length} staged`;
  return (
    <form
      className="flex shrink-0 flex-col gap-2 border-b p-2"
      action={() => {
        if (message.trim() && !disabled) onCommit(message.trim(), () => setMessage(""));
      }}
    >
      <Input
        name="message"
        value={message}
        onChange={(event) => setMessage(event.target.value)}
        placeholder="Commit message"
        className="h-8 text-xs"
        disabled={disabled}
      />
      <Button type="submit" size="sm" disabled={disabled} className="text-xs">
        <GitCommitVerticalIcon className="size-3.5" />
        {label}
      </Button>
    </form>
  );
}

function SectionHeader({ title, buttons }: { title: string; buttons: ReactNode }) {
  return (
    <div className="flex items-center justify-between px-3 pt-2 pb-1">
      <span className="text-[11px] font-semibold tracking-wide text-muted-foreground uppercase">
        {title}
