import { Suspense, lazy, type ComponentType } from "react";
import type { StreamdownProps } from "streamdown";

/** The repo's markdown, rendered. Repo content is whatever its authors and agents committed, so
 *  nothing in it runs: raw HTML is neither parsed nor shown, images are not fetched, and only
 *  http(s) links stay links. */
const Markdown: ComponentType<StreamdownProps> = lazy(async () => {
  const { Streamdown } = await import("streamdown");
  function SafeMarkdown(props: StreamdownProps) {
    return (
      <Streamdown
        mode="static"
        controls={false}
        linkSafety={{ enabled: false }}
        rehypePlugins={[]}
        skipHtml
        disallowedElements={["img"]}
        urlTransform={(url) => (/^https?:\/\//i.test(url) ? url : "")}
        {...props}
      />
    );
  }
  return { default: SafeMarkdown };
});

export function MarkdownPreview({ markdown }: { markdown: string }) {
  return (
    <div className="min-h-0 flex-1 overflow-y-auto">
      <div className="mx-auto w-full max-w-3xl px-8 py-6 text-sm">
        <Suspense
          fallback={
            <div className="text-sm text-muted-foreground" data-spinner="true" role="status">
              Rendering preview…
            </div>
          }
        >
          <Markdown>{markdown}</Markdown>
        </Suspense>
      </div>
    </div>
  );
}

// The repo IDE's reads of one repo: its file list at the tip, kept current by the repo's commits,
// and the reads a page makes once (a file at a commit, a commit's changed files). The project is
// the root context the page holds open; each read opens the repo's handle and lets it go.
import { useCallback, useEffect, useRef, useState, type DependencyList } from "react";
import { z } from "zod";
import type { AuthenticatedApp } from "iterate/app";
import type { RepoLogEntry } from "iterate/api";

export type RepoProject = Awaited<ReturnType<AuthenticatedApp["api"]["projects"]["get"]>>;

export type Read<T> =
  | { status: "pending" }
  | { status: "failed"; message: string }
  | { status: "loaded"; value: T };

const messageOf = (error: unknown) => (error instanceof Error ? error.message : String(error));

/** One async read as render state, made again when `deps` change: the earlier read's answer is
 *  dropped, and until the new one lands the last loaded value stays (a file read again after a
 *  commit does not blink to a spinner and lose the reader's place). */
export function useRead<T>(read: () => Promise<T>, deps: DependencyList): Read<T> {
  const [state, setState] = useState<Read<T>>({ status: "pending" });
  useEffect(() => {
    let current = true;
    setState((previous) => (previous.status === "loaded" ? previous : { status: "pending" }));
    read().then(
      (value) => current && setState({ status: "loaded", value }),
      (error: unknown) => current && setState({ status: "failed", message: messageOf(error) }),
    );
    return () => {
      current = false;
    };
    // `deps` are what `read` closes over
  }, deps);
  return state;
}

export type RepoFiles = { commitOid: string | null; paths: string[] };
export type RepoFilesState = Read<RepoFiles>;

/** The commit events the file list reads: which repo each was to. */
const CommitsCompleted = z.array(z.object({ payload: z.object({ path: z.string() }) }));

/** Calls `onCommit` after each commit to `repoPath`, whoever made it: a commit reaches the page as
 *  the project root's `repo/commit-completed`. `onWatching` runs once the subscription is open, so a
 *  read made then cannot miss a commit between. Answers what stops the watch. */
function watchRepoCommits(
  project: RepoProject,
  repoPath: string,
  handlers: {
    onWatching: () => void;
    onCommit: () => void;
    onError: (error: unknown) => void;
  },
) {
  let closed = false;
  let subscription: Disposable | undefined;
  project
    .subscribe({
      consumes: ["events.iterate.com/repo/commit-completed"],
      target: (events: unknown) => {
        if (CommitsCompleted.parse(events).some((event) => event.payload.path === repoPath))
          handlers.onCommit();
      },
    })
    .then((opened) => {
      if (closed) return opened[Symbol.dispose]();
      subscription = opened;
      handlers.onWatching();
    }, handlers.onError);
  return () => {
    closed = true;
    subscription?.[Symbol.dispose]();
  };
}

/** The repo's files at its tip, read when the page opens and again after each commit to the repo,
 *  whoever made it. `reload` reads now, after this page's own commit. */
export function useRepoFiles(project: RepoProject | undefined, repoPath: string) {
  const [state, setState] = useState<RepoFilesState>({ status: "pending" });
  // each read takes a number: an answer that is not the newest read's is dropped, so a slow read
  // never replaces the list a later one (a commit's) already showed
  const newestRead = useRef(0);

  const read = useCallback(async () => {
    if (!project) return;
    const mine = ++newestRead.current;
    try {
      using repo = project.repos.get(repoPath);
      const value = await repo.listFiles();
      if (mine === newestRead.current) setState({ status: "loaded", value });
    } catch (error) {
      if (mine === newestRead.current) setState({ status: "failed", message: messageOf(error) });
    }
  }, [project, repoPath]);

  useEffect(() => {
    if (!project) return;
    setState({ status: "pending" });
    return watchRepoCommits(project, repoPath, {
      onWatching: () => void read(),
      onCommit: () => void read(),
      onError: (error) => setState({ status: "failed", message: messageOf(error) }),
    });
  }, [project, repoPath, read]);

  return { state, reload: read };
}

/** The repo's newest commits, read while `enabled` (the History sidebar is open) and again when
 *  HEAD moves. */
export function useRepoLog(
  project: RepoProject,
  repoPath: string,
  enabled: boolean,
  headOid: string | null,
) {
  return useRead(async (): Promise<RepoLogEntry[]> => {
    if (!enabled) return [];
    using repo = project.repos.get(repoPath);
    return await repo.log({ limit: 50 });
  }, [project, repoPath, enabled, headOid]);
}

/** A file's text at a commit, or at the tip with no commit; undefined when the repo has no such
 *  file. */
export async function readRepoFile(
  project: RepoProject,
  repoPath: string,
  path: string,
  commitOid?: string,
) {
  using repo = project.repos.get(repoPath);
  const content = await repo.readFile(path, commitOid ? { commitOid } : undefined);
  // oxlint-disable-next-line iterate/simple-truthiness-check -- null is no such file, "" an empty one
  if (content === null) return undefined;
  return content;
}

export type ChangedFile = { path: string; status: "added" | "deleted" | "modified" };

/** The files a commit changed against its first parent, read from both commits' sources. */
export async function readChangedFiles(
  project: RepoProject,
  repoPath: string,
  commit: Pick<RepoLogEntry, "oid" | "parents">,
): Promise<ChangedFile[]> {
  using repo = project.repos.get(repoPath);
  const parent = commit.parents[0];
  const [after, before] = await Promise.all([
    repo.modules({ commitOid: commit.oid }),
    parent ? repo.modules({ commitOid: parent }) : Promise.resolve<Record<string, string>>({}),
  ]);
  const changed: ChangedFile[] = [];
  for (const path of Object.keys({ ...before, ...after }).sort()) {
    if (!(path in before)) changed.push({ path, status: "added" });
    else if (!(path in after)) changed.push({ path, status: "deleted" });
    else if (before[path] !== after[path]) changed.push({ path, status: "modified" });
  }
  return changed;
}

import { useEffect, useEffectEvent, useRef, useState } from "react";
import type { EditorView } from "@codemirror/view";
import { cn } from "cn";
import { editorExtensions, loadCodeMirror } from "./codemirror.ts";
import type { RepoFileLanguage } from "./repo-file-kinds.ts";

/** One file in CodeMirror: line numbers, search, folding, the language's highlighting, and the
 *  editor itself loaded when this first mounts. With a `baseline` (the text it is compared to) it
 *  marks changed lines in the gutter, or with `diff` shows the inline diff, whose chunk controls
 *  stage a chunk through `onAcceptChunk`. The view is made again when `language`, `readOnly`, the
 *  baseline or the diff mode change, from the latest `value`; edits come through `onChange`.
 *  Callers key it by file. */
export function RepoCodeEditor({
  value,
  language,
  label,
  readOnly = false,
  baseline,
  diff = false,
  onAcceptChunk,
  onChange,
  className,
}: {
  value: string;
  language: RepoFileLanguage;
  /** The editor's accessible name: the file's path. */
  label: string;
  readOnly?: boolean;
  baseline?: string;
  diff?: boolean;
  onAcceptChunk?: (baseline: string) => void;
  onChange?: (value: string) => void;
  className?: string;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const viewRef = useRef<EditorView | null>(null);
  const [failure, setFailure] = useState<string | null>(null);
  const emitChange = useEffectEvent((next: string) => onChange?.(next));
  const emitAcceptChunk = useEffectEvent((next: string) => onAcceptChunk?.(next));
  const initialValue = useEffectEvent(() => value);
  const acceptsChunks = Boolean(onAcceptChunk);

  useEffect(() => {
    let cancelled = false;
    let view: EditorView | undefined;
    loadCodeMirror(language).then(
      (cm) => {
        if (cancelled || !containerRef.current) return;
        view = new cm.view.EditorView({
          doc: initialValue(),
          parent: containerRef.current,
          extensions: editorExtensions(cm, {
            language,
            readOnly,
            label,
            baseline,
            diff,
            onAcceptChunk: acceptsChunks ? emitAcceptChunk : undefined,
            onChange: emitChange,
          }),
        });
        viewRef.current = view;
      },
      (error: unknown) => {
        if (!cancelled) setFailure(error instanceof Error ? error.message : String(error));
      },
    );
    return () => {
      cancelled = true;
      view?.destroy();
      viewRef.current = null;
    };
  }, [language, readOnly, label, baseline, diff, acceptsChunks]);

  // A value that changed from outside (a discard, a restore) is dispatched as an edit
  useEffect(() => {
    const view = viewRef.current;
    if (!view) return;
    const current = view.state.doc.toString();
    if (current === value) return;
    view.dispatch({ changes: { from: 0, to: current.length, insert: value } });
  }, [value]);

  if (failure) {
    return (
      <div role="alert" data-type="error" className="p-4 text-sm text-destructive">
        {failure}
      </div>
    );
  }
  return <div ref={containerRef} className={cn("min-h-0 overflow-hidden", className)} />;
}

import { MinusIcon, PencilIcon, PlusIcon, Undo2Icon } from "lucide-react";
import { CodePreviewToggle, EmptyPane, ErrorPane, FileChrome } from "./file-chrome.tsx";
import { HtmlPreview } from "./html-preview.tsx";
import { MarkdownPreview } from "./markdown-preview.tsx";
import { RepoCodeEditor } from "./repo-code-editor.tsx";
import { isPreviewablePath, repoFileKind, type RepoFileLanguage } from "./repo-file-kinds.ts";
import { readRepoFile, useRead, type RepoProject } from "./repo-client.ts";
import { effectiveEntry, type FileChange, type FileEntry } from "./staged-changes.ts";
import { Button } from "#/components/ui/button.tsx";

/** What the pane does to one file's change: the IDE owns the working tree. */
export interface RepoFileHandlers {
  setWorking: (entry: FileEntry | undefined) => void;
  setStaged: (entry: FileEntry | undefined) => void;
  discard: () => void;
  stage: () => void;
  unstage: () => void;
  /** Leave the Index view for the editable working-tree file. */
  openWorking: () => void;
  /** Bring back a file marked for deletion. */
  restore: () => void;
  setDiff: (open: boolean) => void;
  setPreview: (open: boolean) => void;
}

/** How the pane shows the file: the URL's view state. */
export type RepoFileView = {
  diff: boolean;
  /** Markdown, html and svg files: the rendered preview instead of the editor. */
  preview: boolean;
  /** Opened from Staged Changes: a readonly diff of HEAD against the staged snapshot. */
  staged: boolean;
};

type FileStatus = "added" | "deleted" | "modified";

/**
 * The right-hand side of the repo IDE: one file, an editable CodeMirror buffer with a vscode-style
 * inline diff and per-chunk staging, a Code | Preview toggle for markdown and html, or the
 * readonly Index view of what is staged. Files the editor cannot show (images, archives) say so.
 */
export function RepoEditorPane({
  project,
  repoPath,
  path,
  headCommitOid,
  headHasPath,
  change,
  view,
  handlers,
}: {
  project: RepoProject;
  repoPath: string;
  path: string;
  headCommitOid: string | null;
  headHasPath: boolean;
  change: FileChange | undefined;
  view: RepoFileView;
  handlers: RepoFileHandlers;
}) {
  const kind = repoFileKind(path);
  // Keyed by commit oid so a commit, which moves HEAD, reads again; a file never committed has
  // nothing at HEAD to read.
  const headRead = useRead(
    async () =>
      kind.kind === "text" && headHasPath
        ? await readRepoFile(project, repoPath, path, headCommitOid || undefined)
        : undefined,
    [project, repoPath, path, headCommitOid, headHasPath, kind.kind],
  );
  const entry = change && effectiveEntry(change);
  const status: FileStatus | undefined = entry && (headHasPath ? "modified" : "added");

  if (entry?.type === "delete") {
    return (
      <DeletedFile
        path={path}
        staged={change?.staged?.type === "delete"}
        onRestore={handlers.restore}
      />
    );
  }
  if (kind.kind === "binary") {
    return (
      <FileChrome path={path} status={status}>
        <EmptyPane label="Binary file: the repo editor shows text files only." />
      </FileChrome>
    );
  }
  if (headRead.status !== "loaded") {
    return (
      <FileChrome path={path} status={status}>
        {headRead.status === "failed" ? (
          <ErrorPane message={headRead.message} />
        ) : (
          <EmptyPane label={`Loading ${path}…`} spinner />
        )}
      </FileChrome>
    );
  }
  const staged = change?.staged;
  if (view.staged && staged?.type === "write") {
    return (
      <StagedFileView
        path={path}
        language={kind.language}
        status={status}
        stagedText={staged.content}
        headContent={headRead.value}
        preview={view.preview}
        handlers={handlers}
      />
    );
  }
  return (
    <WorkingFileView
      path={path}
      language={kind.language}
      status={status}
      headHasPath={headHasPath}
      headContent={headRead.value}
      change={change}
      view={view}
      handlers={handlers}
    />
  );
}

/** A file marked for deletion: nothing to edit, one way back. */
function DeletedFile({
  path,
  staged,
  onRestore,
}: {
  path: string;
  staged: boolean;
  onRestore: () => void;
}) {
  return (
    <FileChrome path={path} status="deleted">
      <div className="flex flex-1 flex-col items-center justify-center gap-3 text-sm text-muted-foreground">
        <span>
          <span className="font-mono">{path}</span> is {staged ? "staged" : "marked"} for deletion.
        </span>
        <Button variant="outline" size="sm" onClick={onRestore}>
          Restore
        </Button>
      </div>
    </FileChrome>
  );
}

function Preview({ language, text }: { language: RepoFileLanguage; text: string }) {
  return language === "markdown" ? (
    <MarkdownPreview markdown={text} />
  ) : (
    <HtmlPreview html={text} />
  );
}

/** The Index: HEAD against the staged snapshot, readonly, with the same Code | Preview toggle as
 *  the working file. */
function StagedFileView({
  path,
  language,
  status,
  stagedText,
  headContent,
  preview,
  handlers,
}: {
  path: string;
  language: RepoFileLanguage;
  status: FileStatus | undefined;
  stagedText: string;
  headContent: string | undefined;
  preview: boolean;
  handlers: RepoFileHandlers;
}) {
  const previewable = isPreviewablePath(path);
  const showPreview = preview && previewable;
  return (
    <FileChrome
      path={path}
      suffix={showPreview ? "(Index Preview)" : "(Index)"}
      readonly
      status={status}
      leading={
        previewable ? (
          <CodePreviewToggle preview={showPreview} onChange={handlers.setPreview} />
        ) : undefined
      }
      actions={
        <>
          <Button variant="secondary" size="sm" className="text-xs" disabled>
            Diff
          </Button>
          <Button
            variant="ghost"
            size="sm"
            className="text-xs"
            title="Unstage changes"
            onClick={handlers.unstage}
          >
            <MinusIcon className="size-3.5" />
            Unstage
          </Button>
          <Button
            variant="outline"
            size="sm"
            className="text-xs"
            title="Open the editable working tree file"
            onClick={handlers.openWorking}
          >
            <PencilIcon className="size-3.5" />
            Open file
          </Button>
        </>
      }
    >
      {showPreview ? (
        <Preview language={language} text={stagedText} />
      ) : (
        <RepoCodeEditor
          key={`${path}:staged`}
          className="min-h-0 flex-1"
          readOnly
          label={path}
          value={stagedText}
          language={language}
          baseline={headContent || ""}
          diff
        />
      )}
    </FileChrome>
  );
}

/** The editable file: the buffer, its diff against the baseline (the staged snapshot when there is
 *  one, else HEAD), and stage and discard. */
function WorkingFileView({
  path,
  language,
  status,
  headHasPath,
  headContent,
  change,
  view,
  handlers,
}: {
  path: string;
  language: RepoFileLanguage;
  status: FileStatus | undefined;
  headHasPath: boolean;
  headContent: string | undefined;
  change: FileChange | undefined;
  view: RepoFileView;
  handlers: RepoFileHandlers;
}) {
  const working = change?.working;
  const staged = change?.staged;
  // a file never committed and never staged has no baseline to compare to
  const hasBaseline = headHasPath || staged?.type === "write";
  const baseline = staged?.type === "write" ? staged.content : headContent || "";
  const value = working?.type === "write" ? working.content : baseline;
  const previewable = isPreviewablePath(path);
  // Diff wins if a hand-edited URL sets both `preview` and `diff`, so the pane never renders
  // Preview while the header shows the Diff state.
  const showPreview = view.preview && !view.diff && previewable;
  const setBuffer = (content: string) => {
    // typing back to the baseline un-dirties the file, like vscode
    handlers.setWorking(content === baseline ? undefined : { type: "write", content });
  };
  let suffix: string | undefined;
  if (view.diff) suffix = "(Working Tree)";
  else if (showPreview) suffix = "(Preview)";
  return (
    <FileChrome
      path={path}
      suffix={suffix}
      status={status}
      leading={
        previewable ? (
          <CodePreviewToggle preview={showPreview} onChange={handlers.setPreview} />
        ) : undefined
      }
      actions={
        <WorkingFileActions
          showDiff={!showPreview && (headHasPath || Boolean(staged))}
          diff={view.diff}
          dirty={Boolean(working)}
          handlers={handlers}
        />
      }
    >
      {showPreview ? (
        <Preview language={language} text={value} />
      ) : (
        <RepoCodeEditor
          key={path}
          className="min-h-0 flex-1"
          label={path}
          value={value}
          language={language}
          baseline={hasBaseline ? baseline : undefined}
          diff={view.diff}
          onAcceptChunk={(content) =>
            handlers.setStaged(
              content === (headContent || "") ? undefined : { type: "write", content },
            )
          }
          onChange={setBuffer}
        />
      )}
    </FileChrome>
  );
}

/** The header's buttons for an editable file: Diff, and Discard and Stage while it has edits. */
function WorkingFileActions({
  showDiff,
  diff,
  dirty,
  handlers,
}: {
  showDiff: boolean;
  diff: boolean;
  dirty: boolean;
  handlers: RepoFileHandlers;
}) {
  return (
    <>
      {showDiff ? (
        <Button
          variant={diff ? "secondary" : "ghost"}
          size="sm"
          className="text-xs"
          onClick={() => handlers.setDiff(!diff)}
        >
          Diff
        </Button>
      ) : null}
      {dirty ? (
        <>
          <Button
            variant="ghost"
            size="sm"
            className="text-xs"
            title="Discard changes"
            onClick={handlers.discard}
          >
            <Undo2Icon className="size-3.5" />
            Discard
          </Button>
          <Button
            variant="ghost"
            size="sm"
            className="text-xs"
            title="Stage changes"
            onClick={handlers.stage}
          >
            <PlusIcon className="size-3.5" />
            Stage
          </Button>
        </>
      ) : null}
    </>
  );
}

export const NEW_FILE_DISCARD_CONFIRMATION =
  "Are you sure? You may not be able to recover this file";

export function discardRepoFile({
  path,
  headHasPath,
  selected,
  confirmDiscard,
  discardWorking,
  removeWorkingFile,
  closeSelectedFile,
}: {
  path: string;
  headHasPath: boolean;
  selected: boolean;
  confirmDiscard: (message: string) => boolean;
  discardWorking: (path: string) => void;
  removeWorkingFile: (path: string) => void;
  closeSelectedFile: () => void;
}): void {
  if (headHasPath) {
    discardWorking(path);
    return;
  }
  if (!confirmDiscard(NEW_FILE_DISCARD_CONFIRMATION)) return;
  if (selected) closeSelectedFile();
  removeWorkingFile(path);
}

/** The languages the editor highlights. */
export type RepoFileLanguage =
  | "css"
  | "html"
  | "javascript"
  | "json"
  | "jsonc"
  | "markdown"
  | "sql"
  | "text"
  | "typescript"
  | "yaml";

const TEXT_LANGUAGES: Record<string, RepoFileLanguage> = {
  cjs: "javascript",
  css: "css",
  cts: "typescript",
  htm: "html",
  html: "html",
  js: "javascript",
  json: "json",
  jsonc: "jsonc",
  jsx: "javascript",
  markdown: "markdown",
  md: "markdown",
  mjs: "javascript",
  mts: "typescript",
  sql: "sql",
  // svg is xml-ish text; the html grammar highlights it well
  svg: "html",
  ts: "typescript",
  tsx: "typescript",
  yaml: "yaml",
  yml: "yaml",
};

/** Files a text editor cannot show: the repo's reads and commits carry text only. */
const BINARY_EXTENSIONS = new Set([
  "avif",
  "bmp",
  "eot",
  "gif",
  "gz",
  "ico",
  "jar",
  "jpeg",
  "jpg",
  "otf",
  "pdf",
  "png",
  "tar",
  "ttf",
  "wasm",
  "webp",
  "woff",
  "woff2",
  "zip",
]);

/** The `.json` files that allow comments and trailing commas by convention, even without a
 *  `.jsonc` extension: the tsconfig and jsconfig families and VS Code's own config folder. */
function isJsoncByConvention(path: string, basename: string): boolean {
  if (/^(tsconfig|jsconfig).*\.json$/.test(basename)) return true;
  return /(^|\/)\.vscode\/[^/]+\.json$/.test(path);
}

/** How the repo IDE opens a path: in the text editor (with which language), or not at all.
 *  Extension-driven, since repo files have no content type. */
export type RepoFileKind = { kind: "text"; language: RepoFileLanguage } | { kind: "binary" };

export function repoFileKind(path: string): RepoFileKind {
  const basename = path.split("/").pop() ?? path;
  const extension = basename.includes(".") ? basename.split(".").pop()!.toLowerCase() : "";
  if (BINARY_EXTENSIONS.has(extension)) return { kind: "binary" };
  if (isJsoncByConvention(path, basename)) return { kind: "text", language: "jsonc" };
  // everything else opens as text: unknown extensions (Dockerfile, .env, .gitignore, .toml) are
  // overwhelmingly text in project repos
  return { kind: "text", language: TEXT_LANGUAGES[extension] || "text" };
}

/** Files that get the editor pane's Code | Preview toggle: html and svg documents (rendered in a
 *  sandboxed iframe, raw svg markup being valid in an html body) and markdown. */
export function isPreviewablePath(path: string): boolean {
  if (/\.(html?|svg)$/i.test(path)) return true;
  const kind = repoFileKind(path);
  return kind.kind === "text" && kind.language === "markdown";
}

/** The next free `untitled.<extension>` (then `untitled-1.…`) inside a directory. */
export function untitledPath(
  directoryPath: string | null,
  taken: ReadonlySet<string>,
  extension = "txt",
): string {
  const prefix = !directoryPath
    ? ""
    : directoryPath.endsWith("/")
      ? directoryPath
      : `${directoryPath}/`;
  for (let n = 0; ; n++) {
    const candidate = `${prefix}untitled${n === 0 ? "" : `-${n}`}.${extension}`;
    if (!taken.has(candidate)) return candidate;
  }
}

import { useEffect, useRef } from "react";
import { FileTree, useFileTree } from "@pierre/trees/react";
import type {
  ContextMenuItem as TreeContextMenuItem,
  ContextMenuOpenContext as TreeContextMenuOpenContext,
} from "@pierre/trees";
import { FilePlusIcon } from "lucide-react";
import { cn } from "cn";
import { untitledPath } from "./repo-file-tree-paths.ts";
import { Button } from "#/components/ui/button.tsx";

/** The vscode-style git-status letter a changed row wears. */
export type RepoFileStatus = "added" | "deleted" | "modified";

/** Everything a tree row's context menu (and the header button) can do. The IDE owns the change
 *  store and the repo, so the tree only reports intents. */
export interface RepoTreeActions {
  /** Create a brand-new empty text file, already named through the inline rename. May return the
   *  path it actually created when that differs (an extension appended); the tree then drops the
   *  typed row. */
  createFile: (path: string) => string | void;
  /** Delete a file, or every file under a directory. */
  remove: (path: string, isFolder: boolean) => void;
  /** Move a file (or every file under a directory) to a new path. */
  rename: (fromPath: string, toPath: string, isFolder: boolean) => void;
  /** Drop the change for one path: back to HEAD. */
  discard: (path: string) => void;
}

/** The pierre file tree over one repo's HEAD plus its uncommitted changes. Rows carry vscode-style
 *  git-status annotations from the change map (a deleted path stays visible, annotated, until
 *  committed or discarded); right-click offers new file, rename, delete and discard. Renames use
 *  pierre's inline-rename affordance, which doubles as the "name a new file" input. */
export function RepoFileTree({
  headPaths,
  changes,
  selectedPath,
  onSelect,
  actions,
  className,
}: {
  headPaths: string[];
  changes: ReadonlyMap<string, RepoFileStatus>;
  selectedPath: string | undefined;
  onSelect: (path: string) => void;
  actions: RepoTreeActions;
  className?: string;
}) {
  const mergedPaths = mergePaths(headPaths, changes);
  // The pierre callbacks below were bound when the model was made; they reach the latest handlers
  // through refs, written after render.
  const onSelectRef = useRef(onSelect);
  const actionsRef = useRef(actions);
  useEffect(() => {
    onSelectRef.current = onSelect;
    actionsRef.current = actions;
  });
  // While this holds a path, the next rename event is a file creation
  const pendingNewFileRef = useRef<string | null>(null);
  // Only listed files exist: pierre also selects the temporary rows a rename makes
  // react-doctor-disable-next-line react-doctor/rerender-lazy-ref-init -- an empty-container allocation per render is trivial here, and the ??= idiom trips exhaustive-deps instead
  const knownPathsRef = useRef(new Set(mergedPaths));

  const { model } = useFileTree({
    paths: mergedPaths,
    initialExpansion: "open",
    ...(selectedPath && { initialSelectedPaths: [selectedPath] }),
    onSelectionChange: (paths) => {
      const path = paths[0];
      if (!path) return;
      const item = model.getItem(path);
      if (item?.isDirectory() === false && knownPathsRef.current.has(path))
        onSelectRef.current(path);
    },
    renaming: {
      onRename: (event) => {
        const pendingNewFile = pendingNewFileRef.current;
        if (pendingNewFile && event.sourcePath === pendingNewFile) {
          pendingNewFileRef.current = null;
          // The IDE may create the file under another name (an extension appended): drop the
          // typed row, the real one arrives with the next path set. Deferred: pierre moves the
          // row to its typed name only after this callback.
          const created = actionsRef.current.createFile(event.destinationPath);
          if (typeof created === "string" && created !== event.destinationPath) {
            queueMicrotask(() => {
              try {
                model.remove(event.destinationPath);
              } catch {}
            });
          }
          return;
        }
        actionsRef.current.rename(event.sourcePath, event.destinationPath, event.isFolder);
      },
    },
  });

  // Path-set changes sync into the model by adding and removing only what changed (resetPaths
  // would fold every folder the reader opened). Tolerant of rows pierre already moved itself.
  const mergedPathsKey = mergedPaths.join("\n");
  useEffect(() => {
    const next = new Set(mergedPathsKey === "" ? [] : mergedPathsKey.split("\n"));
    const known = knownPathsRef.current;
    for (const path of next) {
      if (!known.has(path))
        try {
          model.add(path);
        } catch {}
    }
    for (const path of known) {
      if (!next.has(path))
        try {
          model.remove(path);
        } catch {}
    }
    knownPathsRef.current = next;
  }, [model, mergedPathsKey]);

  // Keyed on the serialized map so a fresh map every render does not restyle the tree every render
  const statusKey = [...changes].map(([path, status]) => `${path}:${status}`).join("\n");
  useEffect(() => {
    model.setGitStatus(
      statusKey === ""
        ? []
        : statusKey.split("\n").map((line) => {
            // the value after the last colon is the status this key was built from; paths may
            // contain colons, a status never does
            const at = line.lastIndexOf(":");
            return { path: line.slice(0, at), status: line.slice(at + 1) as RepoFileStatus };
          }),
    );
  }, [model, statusKey]);

  const startNewFile = (directoryPath: string | null) => {
    const placeholder = untitledPath(directoryPath, new Set(mergedPaths), "txt");
    pendingNewFileRef.current = placeholder;
    model.add(placeholder);
    model.startRenaming(placeholder, { removeIfCanceled: true });
  };

  return (
    <div className={cn("flex min-h-0 flex-col", className)}>
      <div className="flex shrink-0 items-center gap-0.5 border-b px-2 py-1">
        <span className="px-1 text-[11px] font-semibold tracking-wide text-muted-foreground uppercase">
          Files
        </span>
        <Button
          variant="ghost"
          size="icon-sm"
          title="New file"
          aria-label="New file"
          onClick={() => startNewFile(null)}
          className="ml-auto text-muted-foreground"
        >
          <FilePlusIcon className="size-3.5" />
        </Button>
      </div>
      <FileTree
        model={model}
        className="min-h-0 flex-1 overflow-y-auto"
        // Pierre themes itself with CSS light-dark(); the editor beside it is light only
        // (vsCodeLight), so the tree is pinned to light too
        style={{ colorScheme: "light" }}
        renderContextMenu={(item, context) => (
          <RepoTreeContextMenu
            item={item}
            context={context}
            dirty={changes.has(item.path)}
            onNewFile={(directoryPath) => startNewFile(directoryPath)}
            onStartRename={(path) => model.startRenaming(path)}
            actions={actionsRef.current}
          />
        )}
      />
    </div>
  );
}

function RepoTreeContextMenu({
  item,
  context,
  dirty,
  onNewFile,
  onStartRename,
  actions,
}: {
  item: TreeContextMenuItem;
  context: TreeContextMenuOpenContext;
  dirty: boolean;
  onNewFile: (directoryPath: string) => void;
  onStartRename: (path: string) => void;
  actions: RepoTreeActions;
}) {
  const isFolder = item.kind === "directory";
  return (
    <div className="z-50 flex min-w-36 flex-col gap-0.5 rounded-md border bg-popover p-1 text-popover-foreground shadow-md">
      {isFolder
        ? menuEntry("New file", () => {
            // focus moves into the inline rename input, not back to the row
            context.close({ restoreFocus: false });
            onNewFile(item.path);
          })
        : null}
      {menuEntry("Rename", () => {
        context.close({ restoreFocus: false });
        onStartRename(item.path);
      })}
      {dirty
        ? menuEntry("Discard changes", () => {
            context.close();
            actions.discard(item.path);
          })
        : null}
      {menuEntry(
        "Delete",
        () => {
          context.close();
          actions.remove(item.path, isFolder);
        },
        true,
      )}
    </div>
  );
}

function menuEntry(label: string, onClick: () => void, destructive = false) {
  return (
    <button
      type="button"
      className={cn(
        "w-full rounded-sm px-2 py-1 text-left text-xs hover:bg-accent",
        destructive && "text-destructive",
      )}
      onClick={onClick}
    >
      {label}
    </button>
  );
}

/** All visible tree paths: HEAD's files plus additions; a deletion stays visible, annotated, until
 *  committed or discarded. */
function mergePaths(headPaths: string[], changes: ReadonlyMap<string, RepoFileStatus>): string[] {
  const merged = new Set(headPaths);
  for (const [path, status] of changes) {
    if (status !== "deleted") merged.add(path);
  }
  return [...merged].sort();
}

import { FilesIcon, GitBranchIcon, HistoryIcon, type LucideIcon } from "lucide-react";
import type { RepoIdeSearch } from "./repo-ide-search.ts";
import { Button } from "#/components/ui/button.tsx";

/** The vscode-style strip of sidebars: Files, Source control, History. */
export function RepoIdeActivityStrip({
  search,
  changeCount,
  onSearchChange,
}: {
  search: RepoIdeSearch;
  changeCount: number;
  onSearchChange: (patch: Partial<RepoIdeSearch>) => void;
}) {
  const scm = Boolean(search.scm);
  const history = Boolean(search.history);
  return (
    <div className="flex shrink-0 flex-col items-center gap-1 border-r px-1 py-2">
      <StripButton
        label="Files"
        icon={FilesIcon}
        active={!scm && !history}
        // leaving Source control or History also leaves the pseudo-file (Index, commit diff) it
        // had open
        onClick={() =>
          onSearchChange({
            scm: undefined,
            staged: undefined,
            history: undefined,
            commit: undefined,
          })
        }
      />
      <StripButton
        label="Source control"
        icon={GitBranchIcon}
        active={scm}
        badge={changeCount}
        onClick={() => onSearchChange({ scm: true, history: undefined, commit: undefined })}
      />
      <StripButton
        label="History"
        icon={HistoryIcon}
        active={history}
        onClick={() => onSearchChange({ history: true, scm: undefined, staged: undefined })}
      />
    </div>
  );
}

function StripButton({
  label,
  icon: Icon,
  active,
  badge = 0,
  onClick,
}: {
  label: string;
  icon: LucideIcon;
  active: boolean;
  badge?: number;
  onClick: () => void;
}) {
  return (
    <Button
      variant={active ? "secondary" : "ghost"}
      size="icon"
      title={label}
      // explicit name: the badge inside would otherwise be the accessible name
      aria-label={label}
      onClick={onClick}
      className="relative text-muted-foreground"
    >
      <Icon className="size-4" />
      {badge > 0 ? (
        <span className="absolute -top-0.5 -right-0.5 grid size-4 place-items-center rounded-full bg-primary text-[9px] font-semibold text-primary-foreground">
          {badge}
        </span>
      ) : null}
    </Button>
  );
}

import { z } from "zod";

/** The repo IDE's view state, the route's search so every view is a link: `file` the open path,
 *  `diff` whether the diff against the baseline shows, `preview` whether a markdown or html file
 *  shows its rendered preview instead of the editor, `scm` and `history` which sidebar shows
 *  instead of the file tree, `staged` the readonly Index view of the open file, and `commit` the
 *  expanded commit, whose diff of the open file then shows. */
export const RepoIdeSearch = z.object({
  file: z.string().optional().catch(undefined),
  diff: z.literal(true).optional().catch(undefined),
  preview: z.literal(true).optional().catch(undefined),
  scm: z.literal(true).optional().catch(undefined),
  staged: z.literal(true).optional().catch(undefined),
  history: z.literal(true).optional().catch(undefined),
  commit: z.string().optional().catch(undefined),
});
export type RepoIdeSearch = z.infer<typeof RepoIdeSearch>;

import type { RepoLogEntry } from "iterate/api";
import { CommitDiffPane } from "./commit-diff-pane.tsx";
import { CommitHistoryPanel } from "./commit-history-panel.tsx";
import { EmptyPane, ErrorPane } from "./file-chrome.tsx";
import { GitPanel } from "./git-panel.tsx";
import { RepoEditorPane, type RepoFileHandlers } from "./repo-editor-pane.tsx";
import { RepoFileTree } from "./repo-file-tree.tsx";
import { RepoIdeActivityStrip } from "./repo-ide-activity-strip.tsx";
import type { RepoIdeSearch } from "./repo-ide-search.ts";
import {
  useRepoFiles,
  useRepoLog,
  type Read,
  type RepoFiles,
  type RepoProject,
} from "./repo-client.ts";
import {
  useWorkingTree,
  workingTreeGitStatus,
  workingTreeStore,
  type WorkingTreeChanges,
} from "./staged-changes.ts";
import { useRepoIdeActions } from "./use-repo-ide-actions.ts";

/**
 * The repo IDE: pierre file tree and a CodeMirror editor over one repo's HEAD, with a persistent
 * in-browser working tree (working and staged slots per path, kept in localStorage per HEAD oid)
 * committed through `itx.repos.get(path).commitFiles` as one batch. It fills the space its parent
 * gives it (a flex row with `min-h-0 flex-1`).
 *
 * The IDE's view state (open file, diff, preview, sidebar) is `search`, `RepoIdeSearch`, so a host
 * with a router keeps it in the URL and every view is a link; any host can hold it in state.
 */
export function RepoIde({
  project,
  projectId,
  repoPath,
  author,
  search,
  onSearchChange,
}: {
  /** The project's root context, as the signed-in app holds it. */
  project: RepoProject;
  projectId: string;
  /** `/repos/<name>` */
  repoPath: string;
  /** The commit's author: the person signed in; none leaves the repo's own default. */
  author: { name: string; email: string } | undefined;
  search: RepoIdeSearch;
  onSearchChange: (patch: Partial<RepoIdeSearch>) => void;
}) {
  const { state, reload } = useRepoFiles(project, repoPath);
  if (state.status === "failed") return <ErrorPane message={state.message} />;
  if (state.status === "pending") return <EmptyPane label="Loading repo…" spinner />;
  return (
    <LoadedRepoIde
      project={project}
      projectId={projectId}
      repoPath={repoPath}
      author={author}
      files={state.value}
      reload={reload}
      search={search}
      onSearchChange={onSearchChange}
    />
  );
}

function LoadedRepoIde({
  project,
  projectId,
  repoPath,
  author,
  files,
  reload,
  search,
  onSearchChange,
}: {
  project: RepoProject;
  projectId: string;
  repoPath: string;
  author: { name: string; email: string } | undefined;
  files: RepoFiles;
  reload: () => Promise<void>;
  search: RepoIdeSearch;
  onSearchChange: (patch: Partial<RepoIdeSearch>) => void;
}) {
  // a repo with no commit yet keys its working tree under "unborn"
  const store = workingTreeStore({ projectId, repoPath, commitOid: files.commitOid || "unborn" });
  const changes = useWorkingTree(store);
  const ide = useRepoIdeActions({
    project,
    projectId,
    repoPath,
    author,
    files,
    reload,
    store,
    changes,
    selectedPath: search.file,
    onSearchChange,
  });
  const commits = useRepoLog(project, repoPath, Boolean(search.history), files.commitOid);
  return (
    <div className="flex min-h-0 min-w-0 flex-1 flex-row">
      <RepoIdeActivityStrip
        search={search}
        changeCount={changes.size}
        onSearchChange={onSearchChange}
      />
      <div className="flex min-h-0 w-72 shrink-0 flex-col border-r">
        <RepoIdeSidebar
          project={project}
          repoPath={repoPath}
          files={files}
          commits={commits}
          changes={changes}
          store={store}
          ide={ide}
          search={search}
          onSearchChange={onSearchChange}
        />
      </div>
      <div className="flex min-w-0 flex-1 flex-col">
        <RepoIdeMain
          project={project}
          repoPath={repoPath}
          files={files}
          commits={commits}
          changes={changes}
          store={store}
          ide={ide}
          search={search}
          onSearchChange={onSearchChange}
        />
      </div>
    </div>
  );
}

type Ide = ReturnType<typeof useRepoIdeActions>;
type Store = ReturnType<typeof workingTreeStore>;

/** The sidebar the activity strip chose: the file tree, Source control, or History. */
function RepoIdeSidebar({
  project,
  repoPath,
  files,
  commits,
  changes,
  store,
  ide,
  search,
  onSearchChange,
}: {
  project: RepoProject;
  repoPath: string;
  files: RepoFiles;
  commits: Read<RepoLogEntry[]>;
  changes: WorkingTreeChanges;
  store: Store;
  ide: Ide;
  search: RepoIdeSearch;
  onSearchChange: (patch: Partial<RepoIdeSearch>) => void;
}) {
  if (search.history) {
    if (commits.status !== "loaded") {
      return (
        <div className="p-3 text-xs text-muted-foreground" data-spinner="true">
          {commits.status === "failed" ? commits.message : "Loading history…"}
        </div>
      );
    }
    return (
      <CommitHistoryPanel
        commits={commits.value}
        project={project}
        repoPath={repoPath}
        expandedOid={search.commit}
        selectedPath={search.file}
        onExpand={(oid) => onSearchChange({ commit: oid })}
        // selecting a file clears diff, preview and staged too, so a lingering preview does not
        // reopen for the file picked out of a commit; the commit stays expanded
        onOpenFile={ide.selectFile}
      />
    );
  }
  if (search.scm) {
    return (
      <GitPanel
        changes={changes}
        headPathSet={ide.headPathSet}
        commitPending={ide.committing}
        actions={{
          commit: (message, onCommitted) => void ide.commit(message, onCommitted),
          stage: (path) => store.stage(path),
          unstage: (path) => store.unstage(path),
          discard: ide.discardPath,
          discardAll: () => store.discardAll(),
          open: (path, status) =>
            onSearchChange({
              file: path,
              diff: status === "modified" ? true : undefined,
              preview: undefined,
              staged: undefined,
            }),
          openStaged: (path) =>
            onSearchChange({ file: path, diff: undefined, preview: undefined, staged: true }),
        }}
      />
    );
  }
  return (
    <RepoFileTree
      className="h-full"
      headPaths={files.paths}
      changes={
        new Map(
          workingTreeGitStatus(changes, ide.headPathSet).map((entry) => [entry.path, entry.status]),
        )
      }
      selectedPath={search.file}
      onSelect={ide.selectFile}
      actions={ide.treeActions}
    />
  );
}

/** The open file: the editor, or in History the commit's diff of it. */
function RepoIdeMain({
  project,
  repoPath,
  files,
  commits,
  changes,
  store,
  ide,
  search,
  onSearchChange,
}: {
  project: RepoProject;
  repoPath: string;
  files: RepoFiles;
  commits: Read<RepoLogEntry[]>;
  changes: WorkingTreeChanges;
  store: Store;
  ide: Ide;
  search: RepoIdeSearch;
  onSearchChange: (patch: Partial<RepoIdeSearch>) => void;
}) {
  const path = search.file;
  if (!path) return <EmptyPane label="Select a file to view or edit it." />;

  const expandedCommit =
    commits.status === "loaded" ? commits.value.find((c) => c.oid === search.commit) : undefined;
  if (search.history && expandedCommit) {
    return (
      <CommitDiffPane
        key={`${path}:${expandedCommit.oid}`}
        project={project}
        repoPath={repoPath}
        path={path}
        commit={expandedCommit}
      />
    );
  }

  const change = changes.get(path);
  const handlers: RepoFileHandlers = {
    setWorking: (entry) => store.setWorking(path, entry),
    setStaged: (entry) => store.setStaged(path, entry),
    discard: () => ide.discardPath(path),
    stage: () => store.stage(path),
    unstage: () => {
      store.unstage(path);
      onSearchChange({ staged: undefined });
    },
    openWorking: () => onSearchChange({ staged: undefined, diff: undefined, preview: undefined }),
    restore: () => ide.dropChange(path),
    // diff and preview are exclusive views of the same buffer: one on turns the other off
    setDiff: (open) => onSearchChange({ diff: open ? true : undefined, preview: undefined }),
    setPreview: (open) => onSearchChange({ preview: open ? true : undefined, diff: undefined }),
  };
  return (
    <RepoEditorPane
      key={path}
      project={project}
      repoPath={repoPath}
      path={path}
      headCommitOid={files.commitOid}
      headHasPath={ide.headPathSet.has(path)}
      change={change}
      view={{
        diff: Boolean(search.diff),
        preview: Boolean(search.preview),
        staged: Boolean(search.staged && change?.staged),
      }}
      handlers={handlers}
    />
  );
}

import { useSyncExternalStore } from "react";
import { z } from "zod";
import type { RepoFileChange } from "iterate/api";

const FileEntry = z.discriminatedUnion("type", [
  z.object({ type: z.literal("write"), content: z.string() }),
  z.object({ type: z.literal("delete") }),
]);
export type FileEntry = z.infer<typeof FileEntry>;

export type FileChange = { working?: FileEntry; staged?: FileEntry };

export type WorkingTreeChanges = ReadonlyMap<string, FileChange>;

/** What localStorage holds: entries a version of this store no longer writes fail the parse, and
 *  a store that fails it starts empty. */
const PersistedChanges = z.array(
  z.tuple([z.string(), z.object({ working: FileEntry.optional(), staged: FileEntry.optional() })]),
);

/**
 * The repo IDE's in-browser working tree, git-shaped: every path carries up
 * to two snapshots — `working` (live uncommitted edits) and `staged` (what
 * the next commit will take when anything is staged). Nothing here touches
 * the backend; Commit flushes staged entries (or everything when nothing is
 * staged) through one `repo.commitFiles` batch.
 *
 * Persistence: the whole map mirrors into localStorage keyed by repo AND
 * HEAD commit oid, so a reload keeps your edits — but a HEAD that moved
 * underneath you (someone else committed) orphans the old key instead of
 * producing nonsense diffs against the new checkout.
 */
class WorkingTreeStore {
  #changes: ReadonlyMap<string, FileChange>;
  #listeners = new Set<() => void>();
  readonly storageKey: string;

  constructor(storageKey: string) {
    this.storageKey = storageKey;
    this.#changes = loadPersisted(storageKey);
  }

  /** Stable snapshot — replaced (never mutated) on every change. */
  get changes(): WorkingTreeChanges {
    return this.#changes;
  }

  subscribe = (listener: () => void): (() => void) => {
    this.#listeners.add(listener);
    return () => void this.#listeners.delete(listener);
  };

  /** Set (or with undefined, clear) the live uncommitted edit for a path.
   * An edit identical to the staged snapshot is no edit at all — the file
   * belongs only in Staged Changes then, like vscode. */
  setWorking(path: string, entry: FileEntry | undefined): void {
    this.#patch(path, (change) => ({
      ...change,
      working: entry && change.staged && entriesEqual(entry, change.staged) ? undefined : entry,
    }));
  }

  /** Set (or with undefined, clear) the staged snapshot for a path. A working
   * edit the new snapshot just absorbed (block staging staged the last dirty
   * chunk) is dropped for the same reason. */
  setStaged(path: string, entry: FileEntry | undefined): void {
    this.#patch(path, (change) => ({
      working:
        entry && change.working && entriesEqual(change.working, entry) ? undefined : change.working,
      staged: entry,
    }));
  }

  /** git add: the working entry becomes the staged snapshot. */
  stage(path: string): void {
    this.#patch(path, (change) => ({ staged: change.working || change.staged }));
  }

  /** git reset a path: drop the staged snapshot. Working edits survive; when
   * there are none the staged snapshot becomes the working entry (so the
   * change moves back to Changes instead of vanishing). */
  unstage(path: string): void {
    this.#patch(path, (change) => ({ working: change.working || change.staged }));
  }

  /** Revert a path's live edits to its baseline (staged snapshot, else HEAD). */
  discardWorking(path: string): void {
    this.#patch(path, (change) => ({ staged: change.staged }));
  }

  /** Post-commit cleanup that respects edits made while the commit RPC was in
   * flight: a slot is cleared only while it still equals the entry that was
   * committed; anything newer survives (and migrates to the new HEAD's store). */
  clearCommitted(committed: ReadonlyMap<string, FileEntry>): void {
    const next = new Map(this.#changes);
    for (const [path, entry] of committed) {
      const change = next.get(path);
      if (!change) continue;
      const workingCommitted = change.working && entriesEqual(change.working, entry);
      const working = workingCommitted ? undefined : change.working;
      // a commit of the live edit covers an older staged snapshot of the same path
      const staged =
        workingCommitted || (change.staged && entriesEqual(change.staged, entry))
          ? undefined
          : change.staged;
      if (working || staged) next.set(path, { working, staged });
      else next.delete(path);
    }
    this.#commit(next);
  }

  discardAll(): void {
    if (this.#changes.size === 0) return;
    this.#commit(new Map());
  }

  /** Move every remaining change onto another store (post-commit: HEAD moved,
   * surviving working edits belong to the new oid's key). */
  migrateTo(other: WorkingTreeStore): void {
    if (this === other) return;
    const merged = new Map(other.changes);
    for (const [path, change] of this.#changes) merged.set(path, change);
    other.#commit(merged);
    this.#commit(new Map());
  }

  #patch(path: string, update: (change: FileChange) => FileChange): void {
    const next = new Map(this.#changes);
    const updated = update(next.get(path) ?? {});
    if (updated.working || updated.staged)
      next.set(path, { working: updated.working, staged: updated.staged });
    else next.delete(path);
    this.#commit(next);
  }

  #commit(next: ReadonlyMap<string, FileChange>): void {
    this.#changes = next;
    persist(this.storageKey, next);
    for (const listener of this.#listeners) listener();
  }
}

function entriesEqual(left: FileEntry, right: FileEntry): boolean {
  if (left.type !== right.type) return false;
  if (left.type === "delete") return true;
  return right.type === "write" && left.content === right.content;
}

/**
 * Stores keyed per repo AND HEAD oid, module-level so staged work survives
 * client-side navigation; localStorage carries it across reloads. Stale keys
 * for the same repo at older heads are swept — their diffs would be against
 * a checkout that no longer exists.
 */
const stores = new Map<string, WorkingTreeStore>();

export function workingTreeStore(input: {
  projectId: string;
  repoPath: string;
  commitOid: string;
}) {
  const repoPrefix = `repo-ide-working-tree:${input.projectId}:${input.repoPath}:`;
  const key = `${repoPrefix}${input.commitOid}`;
  const existing = stores.get(key);
  if (existing) return existing;
  sweepStaleKeys(repoPrefix, key);
  const created = new WorkingTreeStore(key);
  stores.set(key, created);
  return created;
}

export function useWorkingTree(store: WorkingTreeStore): WorkingTreeChanges {
  return useSyncExternalStore(
    store.subscribe,
    () => store.changes,
    () => store.changes,
  );
}

/** The change a path currently represents, staged or not. */
export function effectiveEntry(change: FileChange): FileEntry | undefined {
  return change.working || change.staged;
}

/** The pierre-tree git-status annotation for every changed path. */
export function workingTreeGitStatus(
  changes: WorkingTreeChanges,
  headPaths: ReadonlySet<string>,
): Array<{ path: string; status: "added" | "deleted" | "modified" }> {
  return [...changes].flatMap(([path, change]) => {
    const entry = effectiveEntry(change);
    if (!entry) return [];
    return [
      {
        path,
        status:
          entry.type === "delete"
            ? ("deleted" as const)
            : headPaths.has(path)
              ? ("modified" as const)
              : ("added" as const),
      },
    ];
  });
}

/** One working-tree entry as the wire shape `repo.commitFiles` takes. */
function fileChangeForEntry(path: string, entry: FileEntry): RepoFileChange {
  if (entry.type === "delete") return { path, delete: true };
  return { path, content: entry.content };
}

/**
 * What Commit sends: the staged snapshots when anything is staged (vscode's
 * "commit what's staged"), otherwise every change ("commit everything").
 */
export function commitPlan(changes: WorkingTreeChanges): {
  mode: "staged" | "everything";
  paths: string[];
  fileChanges: RepoFileChange[];
  /** What each path was sent as, for `clearCommitted` once the commit lands. */
  entries: Map<string, FileEntry>;
} {
  const staged = [...changes].filter(([, change]) => change.staged);
  const pick = staged.length > 0 ? staged : [...changes];
  const mode = staged.length > 0 ? ("staged" as const) : ("everything" as const);
  const fileChanges: RepoFileChange[] = [];
  const paths: string[] = [];
  const entries = new Map<string, FileEntry>();
  for (const [path, change] of pick) {
    const entry = mode === "staged" ? change.staged : effectiveEntry(change);
    if (!entry) continue;
    paths.push(path);
    entries.set(path, entry);
    fileChanges.push(fileChangeForEntry(path, entry));
  }
  return { mode, paths, fileChanges, entries };
}

function persist(key: string, changes: WorkingTreeChanges): void {
  try {
    if (changes.size === 0) localStorage.removeItem(key);
    else localStorage.setItem(key, JSON.stringify([...changes]));
  } catch {
    // Quota exceeded or storage unavailable: the in-memory store still works,
    // the change just won't survive a reload.
  }
}

function loadPersisted(key: string): ReadonlyMap<string, FileChange> {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return new Map();
    const parsed = PersistedChanges.safeParse(JSON.parse(raw));
    return new Map(parsed.success ? parsed.data : []);
  } catch {
    return new Map();
  }
}

function sweepStaleKeys(repoPrefix: string, currentKey: string): void {
  try {
    const stale: string[] = [];
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key?.startsWith(repoPrefix) && key !== currentKey) stale.push(key);
    }
    for (const key of stale) localStorage.removeItem(key);
  } catch {
    // Storage unavailable — nothing to sweep.
  }
}

// What the repo IDE does to its working tree and its repo: the tree's new, rename, delete and
// discard, and the commit. The working tree is the in-browser store (staged-changes.ts); only a
// commit reaches the repo.
import { useState } from "react";
import { toast } from "sonner";
import { discardRepoFile } from "./repo-file-discard.ts";
import { repoFileKind } from "./repo-file-kinds.ts";
import type { RepoTreeActions } from "./repo-file-tree.tsx";
import type { RepoIdeSearch } from "./repo-ide-search.ts";
import { readRepoFile, type RepoFiles, type RepoProject } from "./repo-client.ts";
import {
  commitPlan,
  effectiveEntry,
  workingTreeStore,
  type FileEntry,
  type WorkingTreeChanges,
} from "./staged-changes.ts";

export function useRepoIdeActions({
  project,
  projectId,
  repoPath,
  author,
  files,
  reload,
  store,
  changes,
  selectedPath,
  onSearchChange,
}: {
  project: RepoProject;
  projectId: string;
  repoPath: string;
  author: { name: string; email: string } | undefined;
  files: RepoFiles;
  reload: () => Promise<void>;
  store: ReturnType<typeof workingTreeStore>;
  changes: WorkingTreeChanges;
  selectedPath: string | undefined;
  onSearchChange: (patch: Partial<RepoIdeSearch>) => void;
}) {
  const [committing, setCommitting] = useState(false);
  const headPaths = files.paths;
  const headPathSet = new Set(headPaths);

  const selectFile = (path: string | undefined) =>
    onSearchChange({ file: path, diff: undefined, preview: undefined, staged: undefined });

  /** The current content of a path: the live edit, the staged snapshot, or HEAD's. Rename fuel. */
  const resolveEntry = async (path: string): Promise<FileEntry> => {
    const current = effectiveEntry(changes.get(path) ?? {});
    if (current && current.type !== "delete") return current;
    if (repoFileKind(path).kind !== "text") throw new Error(`"${path}" is not a text file.`);
    const content = await readRepoFile(project, repoPath, path, files.commitOid || undefined);
    // oxlint-disable-next-line iterate/simple-truthiness-check -- undefined is no such file, "" an empty one
    if (content === undefined) throw new Error(`Repo file does not exist: "${path}".`);
    return { type: "write", content };
  };

  const dropChange = (path: string) => {
    store.setWorking(path, undefined);
    store.setStaged(path, undefined);
  };

  const discardPath = (path: string) =>
    discardRepoFile({
      path,
      headHasPath: headPathSet.has(path),
      selected: selectedPath === path,
      confirmDiscard: (message) => window.confirm(message),
      discardWorking: (trackedPath) => store.discardWorking(trackedPath),
      removeWorkingFile: dropChange,
      closeSelectedFile: () => selectFile(undefined),
    });

  const removePath = (path: string) => {
    // deleting a file never committed drops its change; deleting one at HEAD stages the deletion
    if (headPathSet.has(path)) store.setWorking(path, { type: "delete" });
    else {
      dropChange(path);
      if (selectedPath === path) selectFile(undefined);
    }
  };

  const pathsUnder = (directoryPath: string) => {
    const prefix = `${directoryPath}/`;
    const affected = new Set<string>();
    for (const path of headPaths) if (path.startsWith(prefix)) affected.add(path);
    for (const [path, change] of changes) {
      if (effectiveEntry(change)?.type !== "delete" && path.startsWith(prefix)) affected.add(path);
    }
    return [...affected];
  };

  const rename = async (fromPath: string, toPath: string, isFolder: boolean) => {
    const moves = isFolder
      ? pathsUnder(fromPath).map((path) => ({
          from: path,
          to: `${toPath}${path.slice(fromPath.length)}`,
        }))
      : [{ from: fromPath, to: toPath }];
    try {
      // every source is resolved before anything is staged, so a failed read leaves the working
      // tree untouched (the tree row already moved; the next path sync heals it)
      const resolved = await Promise.all(
        moves.map(async (move) => ({ ...move, entry: await resolveEntry(move.from) })),
      );
      for (const move of resolved) {
        store.setWorking(move.to, move.entry);
        removePath(move.from);
      }
      // the selection follows the rename, a file open inside a renamed folder included
      if (selectedPath === fromPath) selectFile(toPath);
      else if (isFolder && selectedPath?.startsWith(`${fromPath}/`))
        selectFile(`${toPath}${selectedPath.slice(fromPath.length)}`);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Could not rename.");
    }
  };

  const treeActions: RepoTreeActions = {
    createFile: (path) => {
      store.setWorking(path, { type: "write", content: "" });
      selectFile(path);
    },
    discard: discardPath,
    remove: (path, isFolder) => {
      for (const affected of isFolder ? pathsUnder(path) : [path]) removePath(affected);
    },
    rename: (fromPath, toPath, isFolder) => void rename(fromPath, toPath, isFolder),
  };

  const commit = async (message: string, onCommitted: () => void) => {
    setCommitting(true);
    try {
      const plan = commitPlan(changes);
      using repo = project.repos.get(repoPath);
      const result = await repo.commitFiles({
        message,
        changes: plan.fileChanges,
        parent: files.commitOid,
        author,
      });
      // only what was sent goes: an edit or a file made while the commit was in flight stays
      store.clearCommitted(plan.entries);
      // HEAD moved: the working edits that survive belong under the new oid's key. Migrated only
      // after the file list is read again — until then the IDE still reads and writes the old
      // oid's store, and an earlier migration would blank the working tree it shows.
      await reload();
      store.migrateTo(
        workingTreeStore({ projectId, repoPath, commitOid: result.commitOid || "unborn" }),
      );
      onCommitted();
      toast.success(
        result.changedPaths.length === 0
          ? "No changes to commit."
          : `Committed ${result.changedPaths.length} file(s) (${result.commitOid?.slice(0, 7)}).`,
      );
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Could not commit.");
    } finally {
      setCommitting(false);
    }
  };

  return { treeActions, committing, commit, discardPath, dropChange, selectFile, headPathSet };
}
